const item = $input.first().json;
const headers = item.headers ?? {};
const body = item.body && typeof item.body === 'object' ? item.body : item;
const header = (name) => String(headers[name] ?? headers[name.toLowerCase()] ?? headers[name.toUpperCase()] ?? '').trim();
const text = (value) => typeof value === 'string' && value.trim() ? value.trim() : '';
const expectedSecret = String($env.N8N_WEBHOOK_SECRET ?? '').trim();
const errors = [];
if (item.httpMethod && String(item.httpMethod).toUpperCase() !== 'POST') errors.push('Invalid request method.');
if (header('x-zion-source') !== 'backend') errors.push('Invalid source.');
if (!expectedSecret || header('x-zion-workflow-secret') !== expectedSecret) errors.push('Invalid workflow secret.');
if (header('x-zion-event') !== 'booking.created') errors.push('Invalid event.');
if (!text(body.booking_id)) errors.push('Missing booking_id.');
if (!text(body.booking_reference)) errors.push('Missing booking_reference.');
if (!body.categorization || typeof body.categorization !== 'object' || !text(body.categorization.taskTemplateKey)) errors.push('Missing categorization.taskTemplateKey.');
if (header('x-zion-idempotency-key') && header('x-zion-idempotency-key') !== text(body.booking_reference)) errors.push('Invalid idempotency key.');
return [{ json: { authorized: errors.length === 0, errors, booking: { booking_id: text(body.booking_id), booking_reference: text(body.booking_reference), event_type: text(body.event_type) }, categorization: body.categorization ?? {}, workflow: { name: 'Zion - New Booking Orchestration', executionId: String($execution.id), triggeredAt: text(body.triggered_at) || new Date().toISOString() } } }];

const payload = $input.first().json;
if (payload.success !== true || !payload.booking) throw new Error(payload.message || 'Backend booking details response was not successful.');
const booking = payload.booking;
const categorization = payload.categorization ?? $('02. Validate Zion Booking Request').first().json.categorization ?? {};
const eventTime = [booking.start_time, booking.end_time].filter(Boolean).join(' - ') || 'To be confirmed';
return [{ json: { booking, categorization, summary: { bookingReference: booking.booking_reference, clientName: booking.client_name, clientEmail: booking.client_email, eventType: booking.event_type, eventDate: booking.event_date, eventTime, packageName: booking.package_name, guestCount: Number(booking.guest_count) || 0, riskLevel: categorization.riskLevel || 'medium', taskTemplateKey: categorization.taskTemplateKey || 'general_event_standard' }, workflow: { name: 'Zion - New Booking Orchestration', executionId: String($execution.id) } } }];

const source = $('05. Create Structured Booking Summary').first().json;
const booking = source.booking;
const categorization = source.categorization ?? {};
const requestedTemplateKey = categorization.requestedTaskTemplateKey || categorization.taskTemplateKey;
if (!requestedTemplateKey || !booking.booking_id || !booking.booking_reference) throw new Error('Booking template request metadata is incomplete.');
return [{ json: { ...source, taskTemplateRequest: { requestedTemplateKey, bookingId: booking.booking_id, bookingReference: booking.booking_reference, eventCategoryKey: categorization.eventCategoryKey } } }];

const payload = $input.first().json;
const request = $('11A. Prepare Task Template Request').first().json.taskTemplateRequest;
if (payload.success !== true || !payload.template) throw new Error(payload.error || 'Backend task template response was not successful.');
const template = payload.template;
if (!template.id || !template.templateKey || !Number.isInteger(template.version) || !Array.isArray(template.tasks) || template.tasks.length === 0) throw new Error('Task template response is incomplete.');
if (template.requestedTemplateKey !== request.requestedTemplateKey) throw new Error('Task template request key mismatch.');
const orders = new Set();
for (const task of template.tasks) {
  if (!task.templateItemId || !task.itemKey || !Number.isInteger(task.orderIndex) || task.orderIndex < 1 || !task.title || !task.priority || !task.assignedToRole) throw new Error('Task template contains an invalid task.');
  if (orders.has(task.orderIndex)) throw new Error('Task template contains duplicate order values.');
  orders.add(task.orderIndex);
}
return [{ json: { template, taskTemplateRequest: request } }];

const source = $('05. Create Structured Booking Summary').first().json;
const booking = source.booking;
const fetched = $('13A. Validate Task Template Response').first().json;
const template = fetched.template;
const eventDate = new Date(`${booking.event_date}T23:59:59+08:00`);
if (Number.isNaN(eventDate.getTime())) throw new Error('Booking event date is invalid.');
const now = new Date();
const earliest = new Date(now.getTime() + 86400000);
const availableMs = Math.max(eventDate.getTime() - earliest.getTime(), 0);
const calculateDueDate = (task, index, count) => {
  let due;
  if (Number.isInteger(task.dueOffsetDays) && task.dueOffsetDays >= 0) due = new Date(eventDate.getTime() - task.dueOffsetDays * 86400000);
  else due = new Date(earliest.getTime() + availableMs * ((index + 1) / Math.max(count, 1)));
  if (due > eventDate) due = new Date(eventDate);
  const isHighRisk = due < earliest;
  if (isHighRisk) due = new Date(Math.min(earliest.getTime(), eventDate.getTime()));
  return { dueDate: due.toISOString(), isHighRisk };
};
const tasks = template.tasks.map((task, index) => {
  const due = calculateDueDate(task, index, template.tasks.length);
  return { orderIndex: task.orderIndex, title: task.title, description: `${task.description || task.title} Booking: ${booking.booking_reference}.`, priority: task.priority, status: 'pending', activationStatus: 'pending_booking_approval', isActive: false, isEditable: true, category: task.category || 'operations', dueDate: due.dueDate, isHighRisk: due.isHighRisk, assignedToRole: task.assignedToRole, taskTemplateId: template.id, taskTemplateKey: template.templateKey, taskTemplateVersion: template.version, templateItemId: task.templateItemId, itemKey: task.itemKey };
});
const categorization = { ...source.categorization, requestedTaskTemplateKey: template.requestedTemplateKey, taskTemplateKey: template.templateKey, taskTemplateId: template.id, taskTemplateVersion: template.version, templateFallbackUsed: template.isFallback, templateFallbackReason: template.fallbackReason };
return [{ json: { relatedModule: 'booking', relatedRecordId: booking.booking_id, bookingReference: booking.booking_reference, source: 'n8n_workflow', workflowName: 'Zion - New Booking Orchestration', workflowExecutionId: String($execution.id), eventType: booking.event_type, clientName: booking.client_name, categorization, tasks } }];

const taskPayload = $('14A. Prepare Booking-Specific Admin To-Do List').first().json;
const saveResult = $input.first().json;
const createdCount = saveResult.data?.createdCount ?? saveResult.createdCount ?? taskPayload.tasks.length;
const fallbackNote = taskPayload.categorization.templateFallbackUsed ? ` General template fallback was used because ${taskPayload.categorization.requestedTaskTemplateKey} is not published.` : '';
return [{ json: { type: 'NEW_BOOKING_TASK_LIST_CREATED', priority: taskPayload.categorization.templateFallbackUsed ? 'HIGH' : 'MEDIUM', title: `New booking received: ${taskPayload.bookingReference}`, message: `A new ${taskPayload.eventType} booking was submitted. The admin To-Do list is waiting for booking approval.${fallbackNote}`, relatedModule: 'BOOKING', relatedRecordId: taskPayload.relatedRecordId, bookingReference: taskPayload.bookingReference, audience: ['SUPERADMIN', 'ADMIN'], payload: { bookingSummary: { bookingReference: taskPayload.bookingReference, clientName: taskPayload.clientName, eventType: taskPayload.eventType }, categorization: taskPayload.categorization, taskCount: createdCount, tasksPreview: taskPayload.tasks.slice(0, 5).map((task) => ({ orderIndex: task.orderIndex, title: task.title, category: task.category, isHighRisk: task.isHighRisk })) } } }];
